"""优惠券：按券码对金额减免。"""

# 券码 → 处理方式；未知券码抛 ValueError
_SAVE20 = "SAVE20"
_HALF = "HALF"

SAVE20_CUT = 20.0


def apply_coupon(amount, code):
    """按券码对金额应用优惠，返回优惠后金额。

    SAVE20：立减 20 元，减到 0 为止（结果不为负）；
    HALF：打五折；
    其余券码抛 ValueError。
    """
    if code == _SAVE20:
        return max(amount - SAVE20_CUT, 0)
    if code == _HALF:
        return round(amount / 2, 2)
    raise ValueError(f"未知券码: {code}")
